let ac;function chime(){if(!PF.vol)return;try{ac=ac||new(window.AudioContext||window.webkitAudioContext)();const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=880;g.gain.value=.1*PF.vol/100;g.gain.setTargetAtTime(0,ac.currentTime+.05,.08);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+.35)}catch(e){}}
const NH=[];function notify(t,m,k){NH.unshift({t,m,k,at:new Date()});if(NH.length>20)NH.pop();if(PF.dnd)return;const d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.innerHTML=`${ico(k||'about')}<div><b>${esc(t)}</b><div class="mut">${esc(m)}</div></div>`;$('#ts').append(d);chime();while($('#ts').children.length>3)$('#ts').firstChild.remove();setTimeout(()=>{d.classList.add('out');setTimeout(()=>d.remove(),320)},3200)}
