education:{name:'Education',w:620,h:460,render:()=>`<div class="main"><h2>Education</h2><div class="card" style="margin-top:14px"><h3 style="margin:0;font-size:18px;text-transform:none;letter-spacing:0;color:var(--fg)">Manav Rachna International Institute of Research and Studies</h3><div class="mut">Faridabad, India</div><dl class="info"><dt>Degree</dt><dd>Bachelor of Technology, Computer Science Engineering</dd><dt>Duration</dt><dd>Aug 2024 – May 2028 (expected)</dd><dt>CGPA</dt><dd>8.09</dd></dl><h3>Relevant coursework</h3><div>${COURSE.map(c=>`<span class="chip">${c}</span>`).join('')}</div></div></div>`},
