contact:{name:'Contact',w:520,h:440,render:()=>`<div class="main"><h2>Get in touch</h2><p class="mut">Open to software engineering internships and entry-level roles. Email is the fastest way to reach me.</p><div class="card" style="margin:14px 0"><b>Email</b><div>${ME.email}</div><div class="row"><a class="btn p" href="mailto:${ME.email}">Send email</a><button class="btn" data-cp="${ME.email}" data-w="Email">Copy</button></div></div><div class="card" style="margin:14px 0"><b>GitHub</b><div class="mut">${ME.gh}</div><div class="row"><a class="btn" target="_blank" rel="noopener noreferrer" href="${ME.gh}">Open ↗</a><button class="btn" data-cp="${ME.gh}" data-w="GitHub URL">Copy</button></div></div><div class="card"><b>LinkedIn</b><div class="mut">${ME.li}</div><div class="row"><a class="btn" target="_blank" rel="noopener noreferrer" href="${ME.li}">Open ↗</a><button class="btn" data-cp="${ME.li}" data-w="LinkedIn URL">Copy</button></div></div></div>`,bind:el=>$$('[data-cp]',el).forEach(b=>b.onclick=()=>copy(b.dataset.cp,b.dataset.w))},
